import java.util.Scanner;
public class CheckBit {public static boolean isSet(int n,int bit){return bit>=0&&bit<32&&(n&(1<<bit))!=0;}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Number: ");int n=sc.nextInt();System.out.print("Bit index (0-based): ");int b=sc.nextInt();if(b<0||b>31)System.out.println("Bit index must be 0..31");else System.out.println("Set: "+isSet(n,b));sc.close();}}